const items = $input.all();
const body = items[0].json.body || {};

let doctorName = "";
let attendeeEmail = "";
let prospectTimezone = "";

// Extract basic call data - prefer function_calls data over metadata
if (body.function_calls && Array.isArray(body.function_calls)) {
  const bookingCall = body.function_calls.find(fc => fc.name === "book_meeting_slot");
  if (bookingCall) {
    doctorName = bookingCall.params?.name || "";
    attendeeEmail = bookingCall.params?.email || "";
  }
}

// Fallback: use metadata for missing data
if (!doctorName && body.metadata?.doctor_name) {
  doctorName = body.metadata.doctor_name;
}

// Extract timezone from metadata (sent from n8n workflow)
if (body.metadata?.prospect_timezone) {
  prospectTimezone = body.metadata.prospect_timezone;
}

// Enhanced transcript formatting for better readability and AI analysis
const formattedTranscript = (body.chat || [])
  .filter(m => m.content && m.content.trim()) // Remove empty messages
  .map(m => `${m.role === "assistant" ? "Agent" : "Customer"}: ${m.content.trim()}`)
  .join("\n");

// Meeting detection from function calls
const meetingBooked = body.function_calls && 
  body.function_calls.some(fc => fc.name === "book_meeting_slot");

// Extract meeting details if booked
let meetingDetails = {};
if (meetingBooked) {
  const bookingCall = body.function_calls.find(fc => fc.name === "book_meeting_slot");
  if (bookingCall && bookingCall.params) {
    meetingDetails = {
      meeting_date_time: bookingCall.params.start_time || "",
      meeting_timezone: prospectTimezone,
      attendee_name: bookingCall.params.name || doctorName,
      attendee_email: bookingCall.params.email || attendeeEmail,
      attendee_phone: bookingCall.params.phone || ""
    };
  }
}

return [{
  json: {
    call_id: body.call_id,
    doctor_name: doctorName,
    prospect_timezone: prospectTimezone, // NEW: Timezone field
    from_phone: body.voip?.from || "",
    to_phone: (body.voip?.to || "").replace(/"/g, ""), // cleanup quotes
    attendee_email: attendeeEmail,
    call_start_time: new Date(body.ts * 1000).toISOString(),
    call_end_time: new Date((body.ts + body.duration) * 1000).toISOString(),
    transcript: formattedTranscript,
    call_duration_seconds: body.duration || 0,
    meeting_booked: meetingBooked, // Boolean flag
    meeting_details: meetingDetails, // NEW: Structured meeting data
    raw_function_calls: body.function_calls || [],

    // Additional call metadata for analysis
    call_outcome: meetingBooked ? "Meeting Scheduled" : "No Meeting",
    call_quality_score: body.chat ? body.chat.length : 0, // Simple engagement metric
  }
}];

const geminiData = $input.all();
const callData = $('Code').all()[0].json;

console.log("=== GEMINI PROCESSING ===");
console.log("Call Data Keys:", Object.keys(callData));
console.log("Timezone from call:", callData.prospect_timezone);

// Correct path to Gemini response
const geminiResponse = geminiData[0].content?.parts?.[0]?.text || "";
console.log("Raw Gemini Response:", geminiResponse);

let analysisData;
try {
  // Clean the response - remove markdown code blocks and extra whitespace
  let cleanResponse = geminiResponse.replace(/```json\n?|\n?```/g, '').trim();
  console.log("Cleaned Response:", cleanResponse);

  // Parse the JSON
  analysisData = JSON.parse(cleanResponse);
  console.log("Successfully parsed Gemini analysis:", analysisData);

  // Validate required fields
  const requiredFields = ['call_sentiment', 'meeting_booked', 'objection_raised', 'conversion_stage', 'follow_up_needed'];
  const missingFields = requiredFields.filter(field => !(field in analysisData));

  if (missingFields.length > 0) {
    console.log(`Warning: Missing fields: ${missingFields.join(', ')}`);
  }

} catch (error) {
  console.log('Gemini response parsing failed:', error.message);
  console.log('Using enhanced fallback analysis...');

  // Enhanced fallback analysis with timezone awareness
  const transcript = (callData.transcript || '').toLowerCase();
  const meetingBookedInCall = callData.meeting_booked || false;
  const hasTimezoneData = Boolean(callData.prospect_timezone);

  // Analyze transcript for key indicators
  const positiveIndicators = ['yes', 'sounds good', 'let\'s do it', 'perfect', 'great', 'book it', 'schedule'];
  const objectionIndicators = ['busy', 'not interested', 'call back later', 'not now', 'no thanks'];
  const painPointIndicators = ['scheduling', 'billing', 'patients', 'busy', 'time', 'staff', 'insurance'];

  const hasPositiveSignals = positiveIndicators.some(indicator => transcript.includes(indicator));
  const hasObjections = objectionIndicators.some(indicator => transcript.includes(indicator));
  const hasPainPoints = painPointIndicators.some(indicator => transcript.includes(indicator));

  // FIXED: Determine valid objection type for Airtable
  let objectionType = null;
  if (hasObjections) {
    if (transcript.includes('expensive') || transcript.includes('cost') || transcript.includes('price')) {
      objectionType = "Cost";
    } else if (transcript.includes('busy') || transcript.includes('later') || transcript.includes('call me later') || transcript.includes('time')) {
      objectionType = "Timing"; // FIXED: Changed from "Time/Availability" to "Timing"
    } else if (transcript.includes('competitor') || transcript.includes('already using') || transcript.includes('another provider')) {
      objectionType = "Competitor";
    } else if (transcript.includes('not interested')) {
      objectionType = "Not Interested";
    } else {
      objectionType = "Other";
    }
  }

  analysisData = {
    call_sentiment: hasPositiveSignals ? "Positive" : hasObjections ? "Negative" : "Neutral",
    meeting_booked: meetingBookedInCall,
    objection_raised: hasObjections,
    objection_type: objectionType, // Now uses valid Airtable values
    conversion_stage: meetingBookedInCall ? "Closed" : hasPositiveSignals ? "Interested" : "Considering", // FIXED: Changed from "Contacted" to "Considering"
    follow_up_needed: !meetingBookedInCall,
    key_pain_points: hasPainPoints ? "Scheduling and administrative challenges" : "Unknown",
    interest_level: meetingBookedInCall ? "High" : hasPositiveSignals ? "Medium" : "Low",
    decision_maker: meetingBookedInCall,
    timezone_captured: hasTimezoneData,
    analysis_method: "fallback_enhanced"
  };
}

// Validate and fix conversion_stage - ADDED VALIDATION
const validConversionStages = ["Interested", "Considering", "Rejected", "Closed"];
if (!validConversionStages.includes(analysisData.conversion_stage)) {
  console.log(`Invalid conversion_stage: ${analysisData.conversion_stage}, defaulting to Interested`);
  analysisData.conversion_stage = "Interested";
}

// Validate and fix objection_type from Gemini response if needed
if (analysisData.objection_type) {
  const validObjectionTypes = ["Cost", "Timing", "Competitor", "Not Interested", "Other"];

  // If Gemini returns an invalid value, map it to a valid one
  if (!validObjectionTypes.includes(analysisData.objection_type)) {
    console.log(`Invalid objection_type from AI: ${analysisData.objection_type}`);

    // Map common variations to valid values
    const objectionMapping = {
      "time": "Timing",
      "time/availability": "Timing",
      "availability": "Timing",
      "budget": "Cost",
      "money": "Cost",
      "price": "Cost",
      "not interested": "Not Interested",
      "uninterested": "Not Interested",
      "competition": "Competitor",
      "existing solution": "Competitor",
      "contacted": "Considering" // ADDED: Map "contacted" to valid value
    };

    const lowerObjection = analysisData.objection_type.toLowerCase();
    let mappedValue = "Other"; // Default to "Other" if no match

    for (const [key, value] of Object.entries(objectionMapping)) {
      if (lowerObjection.includes(key)) {
        mappedValue = value;
        break;
      }
    }

    analysisData.objection_type = mappedValue;
    console.log(`Mapped to valid value: ${mappedValue}`);
  }
}

// Enhanced logic corrections based on meeting booking status
if (analysisData.meeting_booked) {
  // If meeting was actually booked, ensure consistent analysis
  analysisData.conversion_stage = "Closed";
  analysisData.decision_maker = true;
  analysisData.follow_up_needed = false;
  analysisData.interest_level = "High";

  // If we have meeting details from webhook, include timezone info
  if (callData.meeting_details && callData.prospect_timezone) {
    analysisData.meeting_timezone = callData.prospect_timezone;
    analysisData.timezone_scheduling_success = true;
  }
}

// Additional timezone-specific analysis
if (callData.prospect_timezone) {
  analysisData.prospect_timezone = callData.prospect_timezone;
  analysisData.optimal_call_time = getOptimalCallTime(callData.prospect_timezone);
}

// Function to determine optimal call times based on timezone
function getOptimalCallTime(timezone) {
  const optimalTimes = {
    "Eastern": "10:00 AM - 4:00 PM ET",
    "Central": "10:00 AM - 4:00 PM CT", 
    "Mountain": "10:00 AM - 4:00 PM MT",
    "Pacific": "10:00 AM - 4:00 PM PT"
  };
  return optimalTimes[timezone] || "10:00 AM - 4:00 PM local time";
}

// Calculate call quality metrics
const callQuality = {
  transcript_length: (callData.transcript || '').length,
  call_duration: callData.call_duration_seconds || 0,
  engagement_score: calculateEngagementScore(callData.transcript || '', callData.call_duration_seconds || 0)
};

function calculateEngagementScore(transcript, duration) {
  if (duration < 30) return "Low"; // Very short call
  if (duration > 300 && transcript.length > 500) return "High"; // Long call with good conversation
  if (duration > 120) return "Medium"; // Decent length call
  return "Low";
}

// FINAL VALIDATION - Ensure all Airtable fields are valid before sending
const finalData = {
  ...callData,
  ...analysisData,
  ...callQuality,
  ai_analysis_raw: geminiResponse,
  processing_timestamp: new Date().toISOString(),
  analysis_method: analysisData.analysis_method || "gemini_success",

  // Enhanced fields for better tracking
  call_quality_rating: callQuality.engagement_score,
  timezone_handled_properly: Boolean(callData.prospect_timezone),
  meeting_scheduling_context: callData.meeting_details ? "Complete" : "Partial"
};

// Final safety check - log what we're sending to Airtable
console.log("=== FINAL AIRTABLE DATA ===");
console.log("conversion_stage:", finalData.conversion_stage);
console.log("objection_type:", finalData.objection_type);
console.log("Valid conversion_stage?", validConversionStages.includes(finalData.conversion_stage));

// Combine original call data with AI analysis and enhancements
return [{
  json: finalData
}];
